    14	import org.springframework.stereotype.Service;
    15	import org.springframework.transaction.annotation.Transactional;
    16	
    17	import java.time.LocalDate;
    18	
    19	@Service
    20	@Transactional
    21	public class LoanBookService implements LoanBookUseCase {
    22	
    23	    private final LoadMemberPort loadMemberPort;
    24	    private final CountActiveLoansPort countActiveLoansPort;
    25	    private final LoadBookPort loadBookPort;
    26	    private final SaveBookPort saveBookPort;
    27	    private final SaveLoanPort saveLoanPort;
    28	
    29	    public LoanBookService(LoadMemberPort loadMemberPort,
    30	                           CountActiveLoansPort countActiveLoansPort,
    31	                           LoadBookPort loadBookPort,
    32	                           SaveBookPort saveBookPort,
    33	                           SaveLoanPort saveLoanPort) {
    34	        this.loadMemberPort = loadMemberPort;
    35	        this.countActiveLoansPort = countActiveLoansPort;
    36	        this.loadBookPort = loadBookPort;
    37	        this.saveBookPort = saveBookPort;
    38	        this.saveLoanPort = saveLoanPort;
    39	    }
    40	
    41	    @Override
    42	    public Loan loanBook(LoanBookCommand command) {
    43	        Member member = loadMemberPort.loadMemberForUpdate(command.memberId())
    44	                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
    45	        member.checkCanBorrow(countActiveLoansPort.countActiveLoans(member.getId()));
    46	
    47	        Book book = loadBookPort.loadBook(command.bookId())
    48	                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
    49	        Loan loan = book.loanTo(member.getId(), LocalDate.now());
    50	        saveBookPort.saveBook(book);
    51	        saveLoanPort.saveLoan(loan);
    52	        return loan;
    53	    }
    54	}

